'use strict';
// Vibyra backport: fixed, non-disableable bound for recursive brace walkers.
const MAX_DEPTH = 128;
const checkDepth = depth => {
  if (depth > MAX_DEPTH) throw new SyntaxError('Brace nesting exceeds security limit');
};
const validate = ast => {
  const active = new WeakSet();
  const stack = [[ast, 0, false]];
  while (stack.length) {
    const [node, depth, leaving] = stack.pop();
    checkDepth(depth);
    if (!node || typeof node !== 'object' || Array.isArray(node)) {
      throw new TypeError('Invalid brace AST node');
    }
    if (leaving) { active.delete(node); continue; }
    if (active.has(node)) throw new SyntaxError('Cyclic brace AST');
    for (const descriptor of Object.values(Object.getOwnPropertyDescriptors(node))) {
      if (descriptor.get || descriptor.set) throw new TypeError('Invalid brace AST accessor');
    }
    if (typeof node.type !== 'string' ||
        (node.value !== undefined && typeof node.value !== 'string') ||
        (node.nodes !== undefined && !Array.isArray(node.nodes))) {
      throw new TypeError('Invalid brace AST shape');
    }
    let parent = node.parent;
    const parents = new WeakSet([node]);
    let hops = 0;
    while (parent !== undefined && parent !== null) {
      checkDepth(++hops);
      if (typeof parent !== 'object' || Array.isArray(parent)) {
        throw new TypeError('Invalid brace AST parent');
      }
      if (parents.has(parent)) throw new SyntaxError('Cyclic brace AST parent');
      parents.add(parent);
      const descriptor = Object.getOwnPropertyDescriptor(parent, 'parent');
      if (descriptor && (descriptor.get || descriptor.set)) {
        throw new TypeError('Invalid brace AST accessor');
      }
      parent = parent.parent;
    }
    active.add(node);
    stack.push([node, depth, true]);
    for (const child of node.nodes || []) stack.push([child, depth + 1, false]);
  }
};
module.exports = { MAX_DEPTH, checkDepth, validate };
